    "根据筛选时间，订单合计金额减免掉优惠券、满减/满折、会员折扣后成功支付的金额，再扣除掉积分余额，后实际支付的金额（自提以支付成功后计入统计；不含充值订单）":
        "Based on the selected time range, this is the amount successfully paid after deducting coupons, full-reduction/full-discount promotions, and member discounts from the total order amount, and then deducting points and balance payments. For pickup orders, it is counted after payment succeeds. Recharge orders are excluded.",
