    "根据筛选时间，平台/店铺使用余额支付的金额（不含充值订单）":
        "According to the screening time, the amount paid by the platform/store using balance (excluding recharge orders)",
    "根据筛选时间，平台/店铺售后金额（不含充值订单）": "Based on the screening time, platform/store aftersales amount (excluding recharge orders)",
    "根据筛选时间，平台/店铺售后商品件数（不含充值订单）":
        "Based on the screening time, the number of aftersales products on the platform/store (excluding recharge orders)",
    "根据筛选时间，平台/店铺销售的商品件数": "According to the screening time, the number of products sold on the platform/store",
    "根据筛选时间，平台/店铺销售的营业额，等于实收金额减去售后金额（不含充值订单）":
        "According to the screening time, the turnover of platform/store sales is equal to the actual amount received minus the aftersales amount (excluding recharge orders)",
