    家装: "Home decoration",
    "假设某服装店的T恤衫有S码和M码，并采用了以下阶梯价策略：Ｓ码阶梯价为：1件50元，2-5件每件45元，6件以上40元。Ｍ码阶梯价为：1件40元，2-5件每件35元，6件以上30元。顾客购买了2件S码T恤和6件M码T恤，则总价格为2×45+6×30=270元。":
        "Assume that a clothing store has T-shirts in sizes S and M, and adopts the following tiered price strategy: The tiered price for S size is: 50 CNY for 1 item, 45 CNY for 2–5 items, and 40 CNY for 6 or more pieces. The tiered price for M code is: 40 CNY for 1 item, 35 CNY for 2–5 items each, and 30 CNY for 6 or more pieces. The customer purchased 2 size S T-shirts and 6 size M T-shirts, so the total price is 2×45+6×30=270 CNY.",
    "假设某服装店的T恤衫有S码和M码，S码3件以上，批发价￥100，M码5件以上，批发价90元。 现执行混批策略，顾客购买了2件S码，3件M码，共5件。则总价为100x2+3x90=470。":
        "Assume that a clothing store has T-shirts in sizes S and M. If there are more than 3 pieces of S size, the wholesale price is ￥100, and if there are more than 5 pieces of M size, the wholesale price is 90 CNY. The mixed batch strategy is now implemented, and the customer purchased 2 items in size S and 3 pieces in size M, for a total of 5 pieces. Then the total price is 100x2+3x90=470.",
