    "开启后漏签将重置签到天数；关闭后漏签不会影响签到进度。同一天只能签到一次，达到最大签到天数后将重新从第 1 天开始。":
        "When enabled, a missed day resets the sign-in days; when disabled, missed days do not affect progress. You can sign in once per day, and after the maximum days, the cycle restarts from day 1.",
