    "如：最长预约7天内订单，则买家最早可以选择当天+未来6天内的预约时间":
        "For example, if the maximum reservation time for an order is 7 days, the buyer can choose the earliest reservation time on the same day + within the next 6 days.",
    "如：brand": "Such as: brand",
    "如：brandId": "Such as: brandId",
    "如：brandName": "Such as: brandName",
    "如果不填，则该分类页的标题则为默认标题；如果该项不为空，则该分类页的标题显示此项的内容。":
        "If not filled in, the title of the category page will be the default title; if this item is not empty, the title of the category page will display the content of this item.",
    "如果不填则自动生成，不过有些多音字无法准确判断，如“重”字系统则无法确认是Z还是C":
        'If left blank, it will be automatically generated. However, some multi-phonetic characters cannot be accurately judged. For example, the system for the word "heavy" cannot confirm whether it is Z or C.',
    "如果开启，且配置了H5端域名，移动设备打开PC客户端则会自动跳转到H5端域名":
        "If it is enabled and the H5 domain name is configured, the mobile device will automatically jump to the H5 domain name when opening the PC client.",
    "如果开启则会将区号存入数据库，请谨慎选择（开启后不建议关闭）。":
        "If turned on, the area code will be stored in the database, please choose carefully (it is not recommended to turn it off after turning it on).",
    "如果您不输入商品编码，系统将自动生成一个唯一的编码": "Leave blank to auto-generate a product code",
    "如果您选择了采用服务器内置的 Mail 服务，您不需要填写下面的内容。":
        "If you choose to use the server's built-in Mail service, you do not need to fill in the following content.",
    "如果设置为“未设置的地区使用默认运费设置”，收货地址如果是设置的地区范围内，则按该地区的运费计费，如果不在这范围内，则按默认计费（相当于不会存在不能配送的区域）；":
        'If it is set to "Use default freight settings for unset regions", if the delivery address is within the set region, it will be billed according to the freight in that region. If it is not within this range, it will be billed according to the default (equivalent to there will be no areas that cannot be delivered);',
    "如果是脚本控制的链接，请在此处填入： 请填写http开头的客服链接;":
        "If it is a script-controlled link, please fill in here: Please fill in the customer service link starting with http;",
    "如果为否，订单结算时将不显示发票": "If no, the invoice will not be displayed when the order is settled",
    "如果未设置单独语言图片，则默认使用原图。": "If no language-specific image is set, the original image will be used by default.",
    "如果需要对商品的分类进行变更,那么你可以通过此功能,正确管理你的商品分类。":
        "If you need to change the classification of your products, you can use this function to correctly manage your product classifications.",
    "如果选是，登录页面将显示Google登录快捷入口。如需开通设置，请购买跨境版授权。":
        "If you select Yes, the login page will display the Google login quick entry. If you need to enable settings, please purchase a cross-border version license.",
    "如果选是，登录页面将显示X/Twitter登录快捷入口。如需开通设置，请购买跨境版授权。":
        "If you select Yes, the login page will display the X/Twitter login quick entry. If you need to enable settings, please purchase a cross-border version license.",
    "如果选是，登录页面显示Facebook登录快捷入口，如需开通设置，请购买跨境版授权。":
        "If you select Yes, the login page will display the Facebook login quick entrance. If you need to activate the settings, please purchase the cross-border version authorization.",
    "如果选是，小程序端将显示一键登录": "If you select Yes, the Mini Program will display one-click login",
    "如果选是，则隐藏底部版本号信息。(点击保存后生效)":
        "If yes is selected, the version number information at the bottom will be hidden. (It will take effect after clicking Save)",
    "如果选是，则隐藏浏览器标题栏版权信息": "If yes is selected, the browser title bar copyright information will be hidden.",
    "如果选是，PC端将显示微信扫码登录。": "If you select Yes, the PC will display the WeChat scan code to log in.",
    "如果选是在微信登录时需绑定手机号方可注册，便于全站统一账号；若选择否，则不需要绑定手机，直接注册但不利于账号管理":
        "If you choose Yes, you need to bind your mobile phone number when logging in with WeChat before you can register, which facilitates the unified account for the entire site; if you choose No, you do not need to bind your mobile phone and you can register directly, but it is not conducive to account management.",
    "如果选择了默认国家，则会员在选择地址时默认会显示该国家下的省份或地区，不再显示国家选择（修改设置对已经添加的会员地址不生效）":
        "If a default country is selected, the provinces or regions under that country will be displayed by default when members select addresses, and the country selection will no longer be displayed (the modified settings will not take effect for members who have already added addresses)",
    "如果选指否，则分类不存在时会输出错误；如果选指是，则会自动新建分类！":
        "If you select No, an error will be output if the category does not exist; if you select Yes, a new category will be created automatically!",
    "如何选择？如果所有商品可全国配送，就选“未设置的地区使用默认运费设置”，如果有的商品只配送给部分区域，则选前者，该设置会对全站商品生效，慎重设置！":
        'How to choose? If all products can be delivered nationwide, select "Use default shipping settings for unset areas". If some products are only delivered to certain areas, select the former. This setting will take effect for all products on the site, so set it carefully!',
    "如何选择这种分销模式？": "How to choose a distribution mode?",
    "如你的证件类型是身份证，请在此处上传国徽面，若为复印件，需加盖公司鲜章。注意：证件盖章不支持电子章。":
        "If your document type is an ID card, please upload the national emblem here. If it is a copy, it must be stamped with the company seal. Note: Document stamping does not support electronic stamps.",
    "如你的证件类型是身份证，请在此处上传人像面，若为复印件，需加盖公司鲜章。注意：证件盖章不支持电子章。":
        "If your document type is an ID card, please upload a portrait here. If it is a photocopy, it must be stamped with the company's official seal. Note: Document stamping does not support electronic stamps.",
    "如需联系客户，请点击": "To contact customers, please click",
    "如需修改，请前往微信公众平台-小程序管理-功能-直播进行操作。":
        "If you need to modify it, please go to WeChat Public Platform-Mini Program Management-Function-Live Broadcast to operate.",
