    "下级分销员绑定后，自行购买分销商品即触发": "Triggered once a sub-distributor is bound and purchases distribution products on their own",
    "下级分销员成交后，上级可获得邀请奖励": "After a subordinate distributor completes a sale, the superior can receive invitation rewards",
    下级分销员从哪来: "Where do sub-distributors come from",
    下级分销员邀请奖励: "Subordinate distributor invitation rewards",
    "下级分销员邀请奖励比例：下级分销员绑定后，自行购买分销商品时，上级分销员自动获得邀请奖励 = 下级分销员邀请奖励比例 × 商品实付金额（扣除运费、税费和附加费），无需上级每次再分享推广链接。":
        "Sub-distributor referral reward rate: once a sub-distributor is bound, when they self-purchase a distribution product, the upline distributor automatically earns a referral reward = sub-distributor referral reward rate × actual paid amount (excluding shipping, tax and surcharges); the upline does not need to share the promotion link each time.",
    "下级分销员邀请奖励比例：下级分销员推广后，上级分销员获得邀请奖励=下级分销员邀请奖励比例*商品实付金额（扣除运费、税费和附加费）。":
        "Invitation reward ratio for lower-level distributors: After promotion by lower-level distributors, the upper-level distributors receive invitation rewards = invitation reward ratio for lower-level distributors * actual amount paid for the product (deducting freight, taxes and surcharges).",
