        "If you choose proportional price, the supplier's product will automatically set the sales price according to the markup ratio. The system will automatically calculate the final price after you set the ratio. If the final price you set is greater than the price restricted by the supplier, the system will automatically take the highest ratio set by the supplier for sale.",
