    "开启后，顾客在{shopTerm}下单将自动成为该{shopTerm}客户，{shopTerm}可查看和管理本店客户；关闭后全平台冻结。":
        "When enabled, customers who place orders at the {shopTerm} automatically become customers of that {shopTerm}; the {shopTerm} can view and manage them. When disabled, the feature is frozen platform-wide.",
