        "When enabled, customer nicknames and phone numbers are masked when viewed on the {shopTerm} side. Disabled by default when the master switch is off.",
    "开启后，{shopTerm}端可手动添加客户为本店客户。": "When enabled, the {shopTerm} side can manually add customers to this store.",
